BEGIN;
CREATE TABLE IF NOT EXISTS pc_members(id TEXT PRIMARY KEY,name TEXT NOT NULL,provider TEXT NOT NULL,subject TEXT NOT NULL,UNIQUE(provider,subject));
CREATE TABLE IF NOT EXISTS pc_sessions(hash TEXT PRIMARY KEY,member_id TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS pc_coaches(id TEXT PRIMARY KEY,member_id TEXT NOT NULL UNIQUE,name TEXT NOT NULL,bio TEXT NOT NULL,sport TEXT NOT NULL,region TEXT NOT NULL,kind TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pc_uploads(id TEXT PRIMARY KEY,member_id TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS pc_requests(id TEXT PRIMARY KEY,member_id TEXT NOT NULL,sport TEXT NOT NULL,region TEXT NOT NULL,concern TEXT NOT NULL,upload_id TEXT,created BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS pc_recipients(request_id TEXT NOT NULL,coach_id TEXT NOT NULL,PRIMARY KEY(request_id,coach_id));
CREATE TABLE IF NOT EXISTS pc_feedback(id TEXT PRIMARY KEY,request_id TEXT NOT NULL,coach_id TEXT NOT NULL,body TEXT NOT NULL,created BIGINT NOT NULL,UNIQUE(request_id,coach_id));
CREATE TABLE IF NOT EXISTS pc_lessons(id TEXT PRIMARY KEY,request_id TEXT NOT NULL,coach_id TEXT NOT NULL,member_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',created BIGINT NOT NULL,UNIQUE(request_id,coach_id));
CREATE TABLE IF NOT EXISTS pc_reviews(id TEXT PRIMARY KEY,lesson_id TEXT NOT NULL UNIQUE,coach_id TEXT NOT NULL,member_id TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS pc_request_owner ON pc_requests(member_id,created);
CREATE INDEX IF NOT EXISTS pc_recipient_coach ON pc_recipients(coach_id);

CREATE TABLE IF NOT EXISTS pc_upload_blobs(id TEXT PRIMARY KEY,bytes BYTEA NOT NULL);
COMMIT;
